HERO_STR_STATIC(hero_str_322, "# The Heroes library \342\200\224 Tier 2 of design.md \302\2471.11, written in Heroes itself.");
HERO_STR_STATIC(hero_str_323, "#");
HERO_STR_STATIC(hero_str_324, "# This file is compiled with every program. It is not on disk beside the");
HERO_STR_STATIC(hero_str_325, "# compiler: it is `include_str!`d into the binary, so there is no discovery, no");
HERO_STR_STATIC(hero_str_326, "# `$HEROES_LIBRARY`, and no decoy \342\200\224 clang cannot type-check Heroes source, so a");
HERO_STR_STATIC(hero_str_327, "# file here would have no analogue of the runtime's `_Static_assert` guarding it");
HERO_STR_STATIC(hero_str_328, "# (panel 028 R3).");
HERO_STR_STATIC(hero_str_329, "# Rules for anything added here:");
HERO_STR_STATIC(hero_str_330, "#   - it declares a name from the built-in inventory and nothing else. A helper");
HERO_STR_STATIC(hero_str_331, "#     outside that table would take a name a user program is entitled to;");
HERO_STR_STATIC(hero_str_332, "#   - it is ordinary Heroes, checked by the ordinary rules. That is the whole");
HERO_STR_STATIC(hero_str_333, "#     claim of Tier 2, and \302\2474.11's label rule is the first place it bites:");
HERO_STR_STATIC(hero_str_334, "#     `range`'s two `i64` parameters make its labels mandatory at every call");
HERO_STR_STATIC(hero_str_335, "#     site (panel 028 R1);");
HERO_STR_STATIC(hero_str_336, "#   - a diagnostic raised in this file is a COMPILER BUG, not a user error, and");
HERO_STR_STATIC(hero_str_337, "#     the pipeline reports it as one.");
HERO_STR_STATIC(hero_str_338, "# The integers from `from` up to but not including `to`, in order.");
HERO_STR_STATIC(hero_str_339, "# `to` is excluded, matching `slice(from:, to:)` \342\200\224 the labels and the bound");
HERO_STR_STATIC(hero_str_340, "# answer each other, which is why the spec states both on one line.");
HERO_STR_STATIC(hero_str_341, "# An empty range is not an error: `range(from: 3, to: 3)` and");
HERO_STR_STATIC(hero_str_342, "# `range(from: 5, to: 2)` are both `[]`, so a loop over a range that has run out");
HERO_STR_STATIC(hero_str_343, "# runs zero times rather than aborting.");
HERO_STR_STATIC(hero_str_344, "function range(from: i64, to: i64) -> [i64]");
HERO_STR_STATIC(hero_str_345, "    out: [i64] @ []");
HERO_STR_STATIC(hero_str_346, "    i: i64 @ from");
HERO_STR_STATIC(hero_str_347, "    while i < to");
HERO_STR_STATIC(hero_str_348, "        out @ push(out, i)");
HERO_STR_STATIC(hero_str_349, "        i @ i + 1");
HERO_STR_STATIC(hero_str_350, "    return out");
HERO_STR_STATIC(hero_str_351, "# Each element, transformed. `map(xs, f)` \342\200\224 the signature the spec writes out at");
HERO_STR_STATIC(hero_str_352, "# line 93, which is why this one needs no explaining.");
HERO_STR_STATIC(hero_str_353, "function map<A, B>(xs: [A], f: (function(A) -> B)) -> [B]");
HERO_STR_STATIC(hero_str_354, "    out: [B] @ []");
HERO_STR_STATIC(hero_str_355, "    for x in xs");
HERO_STR_STATIC(hero_str_356, "        out @ push(out, f(x))");
HERO_STR_STATIC(hero_str_357, "# The elements `f` keeps.");
HERO_STR_STATIC(hero_str_358, "function filter<A>(xs: [A], f: (function(A) -> bool)) -> [A]");
HERO_STR_STATIC(hero_str_359, "    out: [A] @ []");
HERO_STR_STATIC(hero_str_360, "        if f(x)");
HERO_STR_STATIC(hero_str_361, "            out @ push(out, x)");
HERO_STR_STATIC(hero_str_362, "# The elements combined into one value, FROM THE LEFT, with the accumulator");
HERO_STR_STATIC(hero_str_363, "# passed FIRST \342\200\224 `f(total, x)`, never `f(x, total)`.");
HERO_STR_STATIC(hero_str_364, "# Both of those are decisions the spec now states (panel 029 R6) and this body is");
HERO_STR_STATIC(hero_str_365, "# what makes them true. They were undecidable from the spec and the wrong guess");
HERO_STR_STATIC(hero_str_366, "# was SILENT: with an accumulator and an element of the same type \342\200\224 `sum`,");
HERO_STR_STATIC(hero_str_367, "# `concat`, `max`, every string builder \342\200\224 either order type-checks and the program");
HERO_STR_STATIC(hero_str_368, "# prints a different answer.");
HERO_STR_STATIC(hero_str_369, "function fold<A, B>(xs: [A], start: B, f: (function(B, A) -> B)) -> B");
HERO_STR_STATIC(hero_str_370, "    total: B @ start");
HERO_STR_STATIC(hero_str_371, "        total @ f(total, x)");
HERO_STR_STATIC(hero_str_372, "    return total");
HERO_STR_STATIC(hero_str_373, "# The first element `f` accepts, or an error. `A?` rather than an index, so the");
HERO_STR_STATIC(hero_str_374, "# caller gets the thing rather than a way to look it up again.");
HERO_STR_STATIC(hero_str_375, "function find<A>(xs: [A], f: (function(A) -> bool)) -> A?");
HERO_STR_STATIC(hero_str_376, "            return ok(x)");
HERO_STR_STATIC(hero_str_377, "    return fail(\"not_found\", \"no element satisfies the test\")");
HERO_STR_STATIC(hero_str_378, "# Does any element pass? Empty is false, which is the same rule as `fold` with a");
HERO_STR_STATIC(hero_str_379, "# `false` start.");
HERO_STR_STATIC(hero_str_380, "function any<A>(xs: [A], f: (function(A) -> bool)) -> bool");
HERO_STR_STATIC(hero_str_381, "            return true");
HERO_STR_STATIC(hero_str_382, "    return false");
HERO_STR_STATIC(hero_str_383, "# Do all of them? Empty is true \342\200\224 vacuously, and it is the answer that makes");
HERO_STR_STATIC(hero_str_384, "# `all(xs, f) == !any(xs, not_f)` hold at every length.");
HERO_STR_STATIC(hero_str_385, "function all<A>(xs: [A], f: (function(A) -> bool)) -> bool");
HERO_STR_STATIC(hero_str_386, "        if !f(x)");
HERO_STR_STATIC(hero_str_387, "            return false");
HERO_STR_STATIC(hero_str_388, "    return true");
HERO_STR_STATIC(hero_str_389, "# The program's three edges (\302\2471.11, panel 036). They are HERE, in Heroes, rather");
HERO_STR_STATIC(hero_str_390, "# than in the compiler, and the argument is worth the four lines it takes.");
HERO_STR_STATIC(hero_str_391, "# \302\2471.7's test is mechanical: a `T?` is a per-translation-unit generated struct,");
HERO_STR_STATIC(hero_str_392, "# so the C runtime cannot name one and `read_file -> str?` cannot be a runtime");
HERO_STR_STATIC(hero_str_393, "# entry point without a second composition form in the emitter. Written here it");
HERO_STR_STATIC(hero_str_394, "# needs none \342\200\224 `ok` and `fail` are the same constructors every other Tier-2");
HERO_STR_STATIC(hero_str_395, "# function uses.");
HERO_STR_STATIC(hero_str_396, "# And the record runs the same way. Pascal predeclared file I/O, command-line");
HERO_STR_STATIC(hero_str_397, "# access and termination; Kernighan's 1981 paper itemises all three as defects;");
HERO_STR_STATIC(hero_str_398, "# Oberon predefines none of them; Nim reaches the same ergonomics from an");
HERO_STR_STATIC(hero_str_399, "# auto-imported module. What crosses to C is only what the language cannot say.");
HERO_STR_STATIC(hero_str_400, "extern \"hero_os.h\"");
HERO_STR_STATIC(hero_str_401, "    # The status codes the wrappers translate, named rather than copied. Before");
HERO_STR_STATIC(hero_str_402, "    # M-header-constants this file compared `status` against `0`, `1` and `2`, and");
HERO_STR_STATIC(hero_str_403, "    # `hero_os.h` says why they were chosen small: *\"small integers rather than");
HERO_STR_STATIC(hero_str_404, "    # errno\"* \342\200\224 a value picked so a Heroes reader could carry it across by hand.");
HERO_STR_STATIC(hero_str_405, "    # Now the header is the only place they are written, and renumbering them there");
HERO_STR_STATIC(hero_str_406, "    # cannot leave this file behind.");
HERO_STR_STATIC(hero_str_407, "    constant HERO_OS_OK: i64");
HERO_STR_STATIC(hero_str_408, "    constant HERO_OS_NOT_FOUND: i64");
HERO_STR_STATIC(hero_str_409, "    function hero_file_read(path: cstr, @status: i64) -> str");
HERO_STR_STATIC(hero_str_410, "    function hero_file_write(path: cstr, text: str) -> i64");
HERO_STR_STATIC(hero_str_411, "    function hero_args_count() -> i64");
HERO_STR_STATIC(hero_str_412, "    function hero_args_at(index: i64) -> str");
HERO_STR_STATIC(hero_str_413, "    function hero_exit(code: i64)");
HERO_STR_STATIC(hero_str_414, "# The whole file, or an error. The two codes are stable snake_case strings");
HERO_STR_STATIC(hero_str_415, "# (\302\2474.6), and they are distinguished because a caller almost always wants to:");
HERO_STR_STATIC(hero_str_416, "# \"there is no such file\" is a different program state from \"the disk failed\".");
HERO_STR_STATIC(hero_str_417, "function read_file(path: str) -> str?");
HERO_STR_STATIC(hero_str_418, "    status: i64 @ 0");
HERO_STR_STATIC(hero_str_419, "    text = hero_file_read(path.cstr(), @status)");
HERO_STR_STATIC(hero_str_420, "    if status == HERO_OS_OK");
HERO_STR_STATIC(hero_str_421, "        return ok(text)");
HERO_STR_STATIC(hero_str_422, "    if status == HERO_OS_NOT_FOUND");
HERO_STR_STATIC(hero_str_423, "        return fail(\"file_not_found\", \"no file at \" + path)");
HERO_STR_STATIC(hero_str_424, "    return fail(\"read_failed\", \"could not read \" + path)");
HERO_STR_STATIC(hero_str_425, "# The text, written whole, replacing whatever was there.");
HERO_STR_STATIC(hero_str_426, "function write_file(path: str, text: str) -> ()?");
HERO_STR_STATIC(hero_str_427, "    if hero_file_write(path.cstr(), text) == HERO_OS_OK");
HERO_STR_STATIC(hero_str_428, "        return ok()");
HERO_STR_STATIC(hero_str_429, "    return fail(\"write_failed\", \"could not write \" + path)");
HERO_STR_STATIC(hero_str_430, "# The arguments after the program's name \342\200\224 the off-by-one every language's first");
HERO_STR_STATIC(hero_str_431, "# CLI program gets wrong, answered in the runtime and stated in the spec.");
HERO_STR_STATIC(hero_str_432, "function args() -> [str]");
HERO_STR_STATIC(hero_str_433, "    out: [str] @ []");
HERO_STR_STATIC(hero_str_434, "    i: i64 @ 0");
HERO_STR_STATIC(hero_str_435, "    while i < hero_args_count()");
HERO_STR_STATIC(hero_str_436, "        out @ push(out, hero_args_at(i))");
HERO_STR_STATIC(hero_str_437, "# Ends the program with this status. It never returns, and the C function it");
HERO_STR_STATIC(hero_str_438, "# calls says so with `_Noreturn` \342\200\224 which is what keeps clang's flow analysis from");
HERO_STR_STATIC(hero_str_439, "# treating the code after it as reachable.");
HERO_STR_STATIC(hero_str_440, "function exit(code: i64)");
HERO_STR_STATIC(hero_str_441, "    hero_exit(code)");
