HERO_STR_STATIC(hero_str_1132, "`int` is not a word in this language \342\200\224 an integer says its width: `i64`, and also `i8` `i16` `i32` `u8` `u16` `u32` `u64`");
HERO_STR_STATIC(hero_str_1133, "i64");
HERO_STR_STATIC(hero_str_1134, "`struct` is not a word in this language \342\200\224 use `record`: `record Point`");
HERO_STR_STATIC(hero_str_1135, "`enum` is not a word in this language \342\200\224 use `variant`: `variant Token`");
HERO_STR_STATIC(hero_str_1136, "`union` is not a word in this language \342\200\224 use `variant`: `variant Token`");
HERO_STR_STATIC(hero_str_1137, "`class` is not a word in this language \342\200\224 use `record` (there is no inheritance)");
HERO_STR_STATIC(hero_str_1138, "`fn` is not a word in this language \342\200\224 use `function`: `function f(x: i64) -> i64`");
HERO_STR_STATIC(hero_str_1139, "`func` is not a word in this language \342\200\224 use `function`");
HERO_STR_STATIC(hero_str_1140, "`def` is not a word in this language \342\200\224 use `function`");
HERO_STR_STATIC(hero_str_1141, "`let` is not a word in this language \342\200\224 bind with `=`: `x = 5`");
HERO_STR_STATIC(hero_str_1142, "`var` is not a word in this language \342\200\224 declare a mutable with `@`: `v: i64 @ 0`");
HERO_STR_STATIC(hero_str_1143, "`const` is not a word in this language \342\200\224 use `constant`: `constant MAX: i64`");
HERO_STR_STATIC(hero_str_1144, "`elif` is not a word in this language \342\200\224 write `else if`");
HERO_STR_STATIC(hero_str_1145, "else if");
HERO_STR_STATIC(hero_str_1146, "`switch` is not a word in this language \342\200\224 use `match`");
HERO_STR_STATIC(hero_str_1147, "`case` is not a word in this language \342\200\224 a `match` arm is `.name => expr`");
HERO_STR_STATIC(hero_str_1148, "there is no null in this language \342\200\224 absence is a fallible type: `i64?`, and a C pointer's zero is `nullptr`");
HERO_STR_STATIC(hero_str_1149, "there are no exceptions in this language \342\200\224 errors are values: `fail(code, msg)`, propagate with `?`");
HERO_STR_STATIC(hero_str_1150, "`import` and `include` are not words in this language \342\200\224 a module is named with `use`: `use geom`");
