HERO_STR_STATIC(hero_str_1163, "base_prefix_case");
HERO_STR_STATIC(hero_str_1164, "` writes the base in uppercase \342\200\224 this language spells it `");
HERO_STR_STATIC(hero_str_1165, "there is exactly one way to write any program (\302\2474.15). The ");
HERO_STR_STATIC(hero_str_1166, " digits themselves may be either case, so `");
HERO_STR_STATIC(hero_str_1167, "` is the same value written correctly");
HERO_STR_STATIC(hero_str_1168, "write the prefix as `");
HERO_STR_STATIC(hero_str_1169, "` starts with a zero, and this language reads no meaning into that");
HERO_STR_STATIC(hero_str_1170, "C, and every language that copied it, reads a leading zero as octal \342\200\224 so `");
HERO_STR_STATIC(hero_str_1171, "` is a number a reader will size wrong. Write `0o");
HERO_STR_STATIC(hero_str_1172, "` for the octal value, or `");
HERO_STR_STATIC(hero_str_1173, "` for the decimal one");
HERO_STR_STATIC(hero_str_1174, "octal: `0o");
HERO_STR_STATIC(hero_str_1175, "0o");
HERO_STR_STATIC(hero_str_1176, "decimal: `");
HERO_STR_STATIC(hero_str_1177, "exponent_literal");
HERO_STR_STATIC(hero_str_1178, "` is not a number in this language \342\200\224 there are no exponents. Write the digits out, or compute it: `");
HERO_STR_STATIC(hero_str_1179, " * pow(base: 10.0, exponent: \342\200\246)` through the FFI (\302\2474.19)");
HERO_STR_STATIC(hero_str_1180, "empty_base_literal");
HERO_STR_STATIC(hero_str_1181, "` names a base and then stops \342\200\224 a number needs digits");
HERO_STR_STATIC(hero_str_1182, " literal is written `");
HERO_STR_STATIC(hero_str_1183, "` followed by ");
HERO_STR_STATIC(hero_str_1184, "misplaced_separator");
HERO_STR_STATIC(hero_str_1185, "`_` groups digits, so it goes between two of them");
HERO_STR_STATIC(hero_str_1186, "`1_000_000` and `0xff_ff` are the shape; a separator that leads, trails or doubles is a typo rather than a grouping");
